import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { SrdKind } from "../src/schema/index.js";

export const pkgRoot = join(dirname(fileURLToPath(import.meta.url)), "..");

/** The five kinds generated by the original conversion. `rule` has its own tests (rule.test.ts). */
export type LegacyKind = Exclude<SrdKind, "rule">;

export const KINDS: readonly LegacyKind[] = [
  "monster",
  "spell",
  "class",
  "equipment",
  "condition",
];

export function readJson(relative: string): unknown {
  return JSON.parse(readFileSync(join(pkgRoot, relative), "utf8"));
}

/** Record fields these tests rely on; the full shape is checked by the schemas. */
export interface Rec {
  id: string;
  name: string;
  source: { document: string; section: string; page: number };
  [key: string]: unknown;
}

export function readData(kind: SrdKind): Rec[] {
  return readJson(`data/${kind}.json`) as Rec[];
}

export interface IndexEntry {
  name: string;
  page: number;
  embedded?: string;
}

export interface RuleIndexEntry {
  id: string;
  path: string[];
  page: number;
}

export interface Index {
  document: string;
  pdfSha256: string;
  pdfUrl: string;
  kinds: Record<LegacyKind, IndexEntry[]> & { rule: RuleIndexEntry[] };
}

export function readIndex(): Index {
  return readJson("provenance/srd-5.2.1-index.json") as Index;
}

/** Name comparison form: case, curly apostrophes, diacritics and spacing do not matter. */
export function normalizeName(name: string): string {
  return name
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[‘’]/g, "'")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

/** Hand-written rule record for fixture tests; override any field. Not SRD text. */
export function ruleFixture(overrides: Record<string, unknown> = {}): Rec {
  return {
    id: "playing-the-game.fixture",
    name: "Playing the Game › Fixture",
    title: "Fixture",
    path: ["Playing the Game", "Fixture"],
    parent: null,
    children: [],
    source: { document: "SRD 5.2.1", section: "Playing the Game", page: 7 },
    pageEnd: 7,
    blocks: [{ type: "text", text: "A fixture sentence." }],
    ...overrides,
  };
}
